/**
 * ALO Labs AgentOS — central API security layer.
 *
 * Every route handler that mutates tenant data must be wrapped with
 * `secureRoute` (or generated by `secureCrud`). The wrapper enforces, in a
 * fixed order:
 *
 *   1. request id                     — correlations for tracing and support
 *   2. optional pre-auth rate limit   — brute-force protection (public routes)
 *   3. authentication                 — session bearer tokens and company API keys
 *   4. tenant resolution              — ALWAYS derived from the principal, never
 *                                       from the request body
 *   5. rate limit (principal bucket)  — keyed on the authenticated principal so
 *                                       it cannot be bypassed by spoofing
 *                                       X-Forwarded-For or any other header
 *   6. API-key scope check            — scoped keys stay scoped
 *   7. role based authorisation       — global role and/or company role
 *   8. Zod validation                 — params (400), query (400), body (422)
 *   9. tenant-authority check         — a `companyId` supplied by the client must
 *                                       match the principal's tenant, otherwise
 *                                       the request is refused and recorded
 *  10. handler                        — errors are mapped to a uniform envelope
 *
 * Security events are written to the `SecurityEvent` table for authentication
 * failures, authorisation failures, tenant violations and rate-limit breaches.
 * Event metadata is redacted: no tokens, credentials, request bodies, e-mail
 * addresses or other personal data are ever persisted.
 *
 * Existing authentication mechanisms are preserved — this module composes
 * `getAuthUser()` (session + `x-company-id` membership validation) and
 * `authenticateV1()` (session fallback + company API keys) rather than
 * replacing them.
 */

import { randomUUID } from 'node:crypto';
import { NextResponse } from 'next/server';
import type { NextRequest } from 'next/server';
import { z } from 'zod';
import { getAuthUser } from '@/lib/api-auth';
import { authenticateV1 } from '@/lib/v1-auth';
import { checkRateLimit } from '@/lib/rate-limiter';
import { db } from '@/lib/db';

// ─── Roles ───────────────────────────────────────────────────────────────────

/** Global roles that satisfy any role or company-role requirement. */
export const ADMIN_ROLES: readonly string[] = ['super_admin', 'admin'];

// ─── Errors ──────────────────────────────────────────────────────────────────

export type ApiErrorCode =
  | 'unauthorized'
  | 'forbidden'
  | 'tenant_required'
  | 'tenant_mismatch'
  | 'not_found'
  | 'invalid_json'
  | 'invalid_body'
  | 'invalid_query'
  | 'invalid_params'
  | 'rate_limited'
  | 'conflict'
  | 'internal_error';

export class ApiHttpError extends Error {
  public readonly status: number;
  public readonly code: ApiErrorCode;
  public readonly details?: unknown;
  /** Set once the failure has been written to the security audit trail. */
  public recorded = false;

  constructor(status: number, code: ApiErrorCode, message: string, details?: unknown) {
    super(message);
    this.name = 'ApiHttpError';
    this.status = status;
    this.code = code;
    if (details !== undefined) this.details = details;
  }
}

/** Failures that must leave a trace in the security event log. */
const SECURITY_ERROR_CODES = new Set<ApiErrorCode>([
  'unauthorized',
  'forbidden',
  'tenant_required',
  'tenant_mismatch',
]);

export const badRequest = (message = 'Invalid request', details?: unknown) =>
  new ApiHttpError(400, 'invalid_query', message, details);
export const unprocessable = (message = 'Invalid request body', details?: unknown) =>
  new ApiHttpError(422, 'invalid_body', message, details);
export const notFound = (message = 'Not found') => new ApiHttpError(404, 'not_found', message);
export const conflict = (message = 'Conflict', details?: unknown) =>
  new ApiHttpError(409, 'conflict', message, details);
export const forbidden = (message = 'Forbidden', code: ApiErrorCode = 'forbidden') =>
  new ApiHttpError(403, code, message);

/**
 * Uniform error envelope. `success: false` is retained because the legacy
 * routes it replaces returned that flag and clients already depend on it.
 */
export function errorResponse(
  status: number,
  code: ApiErrorCode,
  message: string,
  requestId: string,
  details?: unknown,
  headers?: Record<string, string>,
): NextResponse {
  const body: Record<string, unknown> = {
    error: { code, message, ...(details === undefined ? {} : { details }) },
    requestId,
    success: false,
  };
  return NextResponse.json(body, { status, headers: { 'x-request-id': requestId, ...(headers ?? {}) } });
}

/** Pass-through success response that stamps the request id for tracing. */
export function jsonResponse(
  data: unknown,
  requestId: string,
  status = 200,
  headers?: Record<string, string>,
): NextResponse {
  return NextResponse.json(data, { status, headers: { 'x-request-id': requestId, ...(headers ?? {}) } });
}

// ─── Principal ───────────────────────────────────────────────────────────────

export interface Principal {
  kind: 'session' | 'apiKey';
  userId: string;
  role: string;
  email: string;
  name: string;
  /** Resolved tenant. `undefined` only when the principal has no membership. */
  companyId?: string;
  /** Role inside the resolved tenant (membership role). */
  companyRole?: string;
  scopes: string[];
  keyId?: string;
}

async function resolvePrincipal(request: NextRequest): Promise<Principal | null> {
  // Legacy path first: it honours the `x-company-id` / `x-company-slug` headers
  // and validates the requested tenant against the user's memberships.
  const legacy = await getAuthUser();
  if (legacy) {
    return {
      kind: 'session',
      userId: legacy.userId,
      role: legacy.role,
      email: legacy.email,
      name: legacy.name,
      ...(legacy.companyId ? { companyId: legacy.companyId } : {}),
      ...(legacy.companyRole ? { companyRole: legacy.companyRole } : {}),
      scopes: ['*'],
    };
  }
  // v1 path: company API keys, plus a session fallback for users whose tenant
  // was not resolved above.
  const v1 = await authenticateV1(request);
  if (v1) {
    return {
      kind: v1.kind,
      userId: v1.userId,
      role: v1.role,
      email: v1.email,
      name: v1.name,
      companyId: v1.companyId,
      scopes: v1.scopes ?? [],
      ...(v1.keyId ? { keyId: v1.keyId } : {}),
    };
  }
  return null;
}

// ─── Security events ─────────────────────────────────────────────────────────

const REDACTED_KEY_PATTERN =
  /(token|password|passwd|secret|authorization|cookie|api[-_]?key|email|phone|ssn|card|cvv|otp)/i;

/**
 * Remove credentials and personal data before anything is persisted.
 * Non-plain-object values are replaced by a type tag; strings are truncated.
 */
export function redact(value: unknown, depth = 0): unknown {
  if (value == null) return null;
  if (depth > 4) return '[truncated]';
  if (typeof value === 'string') return value.length > 200 ? `${value.slice(0, 200)}…` : value;
  if (typeof value === 'number' || typeof value === 'boolean') return value;
  if (Array.isArray(value)) return value.slice(0, 20).map((entry) => redact(entry, depth + 1));
  if (typeof value === 'object') {
    const output: Record<string, unknown> = {};
    for (const [key, entry] of Object.entries(value as Record<string, unknown>)) {
      if (REDACTED_KEY_PATTERN.test(key)) {
        output[key] = '[redacted]';
        continue;
      }
      output[key] = redact(entry, depth + 1);
    }
    return output;
  }
  return String(typeof value);
}

export interface SecurityEventInput {
  type: string;
  severity: 'low' | 'medium' | 'high' | 'critical';
  resource: string;
  action: string;
  requestId: string;
  principal?: Pick<Principal, 'userId' | 'kind' | 'role' | 'keyId'> | null;
  companyId?: string | null;
  details?: Record<string, unknown>;
  riskScore?: number;
}

/**
 * Best-effort security audit trail. Never throws: observability must not be
 * able to take a route down, and never stores credentials or personal data.
 */
export async function recordSecurityEvent(input: SecurityEventInput): Promise<void> {
  try {
    await db.securityEvent.create({
      data: {
        type: input.type,
        severity: input.severity,
        source: `${input.resource}:${input.action}`,
        companyId: input.companyId ?? null,
        action: input.action,
        riskScore: input.riskScore ?? null,
        details: JSON.stringify(
          redact({
            requestId: input.requestId,
            resource: input.resource,
            principalId: input.principal?.userId ?? null,
            principalKind: input.principal?.kind ?? null,
            principalRole: input.principal?.role ?? null,
            keyId: input.principal?.keyId ?? null,
            ...(input.details ?? {}),
          }),
        ),
      },
    });
  } catch {
    // Intentionally swallowed — a failed audit write must not fail the request.
  }
}

// ─── Route wrapper ───────────────────────────────────────────────────────────

/**
 * Resolve which tenant a request may act on.
 *
 * `super_admin` may name any tenant — cross-tenant administration is that
 * role's job. Every other principal is pinned to their own tenant: naming a
 * different one is refused (403) rather than silently ignored, so a caller can
 * never read or write another tenant's records by editing `companyId`.
 */
export function tenantTarget(
  principal: { role?: string | null; companyId?: string | null } | null | undefined,
  requested?: string | null,
): { ok: true; companyId: string } | { ok: false; status: 400 | 403; error: string } {
  const own = principal?.companyId ?? '';
  const requestedId = typeof requested === 'string' && requested.length > 0 ? requested : null;

  if (principal?.role === 'super_admin') {
    const resolved = requestedId ?? own;
    if (!resolved) return { ok: false, status: 400, error: 'companyId is required' };
    return { ok: true, companyId: resolved };
  }

  if (!own) return { ok: false, status: 403, error: 'Tenant context required' };
  if (requestedId && requestedId !== own) {
    return { ok: false, status: 403, error: 'Tenant mismatch: companyId does not match the authenticated principal' };
  }
  return { ok: true, companyId: own };
}

export type SecureAction = 'read' | 'create' | 'update' | 'delete' | 'execute';

export interface RateLimitPolicy {
  limit: number;
  windowMs: number;
  /** Also rate-limit unauthenticated callers on a shared bucket (public routes). */
  preAuth?: boolean;
}

export interface SecureRouteOptions<TBody = unknown, TQuery = unknown, TParams = unknown> {
  /** Dotted resource name, e.g. `crm.contacts`. Used in events and rate-limit keys. */
  resource: string;
  action?: SecureAction;
  /** `required` (default) rejects anonymous callers with 401. */
  auth?: 'required' | 'optional';
  /** `required` (default) rejects principals without a tenant with 403. */
  tenant?: 'required' | 'optional' | 'none';
  /** Allowed global roles. Administrators always pass. */
  roles?: readonly string[];
  /** Allowed membership roles inside the tenant. Administrators always pass. */
  companyRoles?: readonly string[];
  /** Required scope when the caller authenticates with a company API key. */
  scope?: string;
  rateLimit?: RateLimitPolicy | false;
  body?: z.ZodType<TBody>;
  query?: z.ZodType<TQuery>;
  params?: z.ZodType<TParams>;
  /**
   * Status returned for an invalid body. Defaults to 422; set to 400 for
   * routes whose clients already depend on 400.
   */
  bodyStatus?: 400 | 422;
}

export interface SecureContext<TBody = unknown, TQuery = unknown, TParams = unknown> {
  request: NextRequest;
  requestId: string;
  principal: Principal;
  /** Server-authoritative tenant id. Empty string when `tenant: 'none'`. */
  companyId: string;
  body: TBody;
  query: TQuery;
  params: TParams;
  /** Throw 404 unless the record belongs to the caller's tenant. */
  assertTenant: (recordCompanyId: string | null | undefined) => void;
  /** Prisma `where` fragment scoped to the caller's tenant. */
  tenantWhere: <T extends Record<string, unknown>>(extra?: T) => Record<string, unknown>;
}

export type SecureHandler<TBody, TQuery, TParams> = (
  context: SecureContext<TBody, TQuery, TParams>,
) => Promise<NextResponse | unknown> | NextResponse | unknown;

interface RouteContextShape {
  params?: unknown;
}

function isAdmin(principal: Principal): boolean {
  return ADMIN_ROLES.includes(principal.role);
}

function searchParamsToObject(searchParams: URLSearchParams): Record<string, unknown> {
  const output: Record<string, unknown> = {};
  for (const key of new Set(searchParams.keys())) {
    const all = searchParams.getAll(key);
    output[key] = all.length > 1 ? all : all[0];
  }
  return output;
}

/**
 * Refuse a client-supplied tenant identifier that does not belong to the
 * authenticated principal. Runs BEFORE schema validation so an attempt is
 * always rejected and recorded instead of being silently stripped.
 */
function assertTenantAuthority(
  value: unknown,
  companyId: string,
  tenantMode: 'required' | 'optional' | 'none',
): void {
  if (tenantMode === 'none') return;
  if (!value || typeof value !== 'object') return;
  const supplied = (value as Record<string, unknown>).companyId;
  if (typeof supplied !== 'string' || supplied.length === 0) return;
  if (supplied !== companyId) {
    throw new ApiHttpError(403, 'tenant_mismatch', 'Tenant mismatch: companyId does not match the authenticated principal');
  }
}

/**
 * Remove the tenant identifier AFTER validation: schemas may still require
 * `companyId` to be present (legacy request contracts), but no handler may
 * read the client's value — the authoritative one comes from the principal.
 */
function stripTenantAuthority(value: unknown): void {
  if (!value || typeof value !== 'object') return;
  delete (value as Record<string, unknown>).companyId;
}

async function readJsonBody(request: NextRequest): Promise<unknown> {
  try {
    return await request.json();
  } catch {
    throw new ApiHttpError(400, 'invalid_json', 'Request body must be valid JSON');
  }
}

export function secureRoute<TBody = unknown, TQuery = unknown, TParams = unknown>(
  options: SecureRouteOptions<TBody, TQuery, TParams>,
  handler: SecureHandler<TBody, TQuery, TParams>,
) {
  const authMode = options.auth ?? 'required';
  const tenantMode = options.tenant ?? 'required';
  const action = options.action ?? 'read';

  return async (request: NextRequest, routeContext?: RouteContextShape): Promise<NextResponse> => {
    const requestId = randomUUID();
    const rateLimit = options.rateLimit === false ? null : options.rateLimit ?? null;
    // Kept outside the try so the error path can attribute the event.
    let activePrincipal: Principal | null = null;

    try {
      // 2. Pre-auth bucket: shared across all anonymous callers so that header
      //    spoofing cannot buy extra attempts.
      if (rateLimit?.preAuth) {
        const pre = await checkRateLimit(`anon:${options.resource}:${action}`, rateLimit.limit, rateLimit.windowMs);
        if (!pre.allowed) {
          await recordSecurityEvent({
            type: 'rate_limit_exceeded',
            severity: 'medium',
            resource: options.resource,
            action,
            requestId,
            details: { phase: 'pre-auth', limit: rateLimit.limit },
          });
          return errorResponse(429, 'rate_limited', 'Too many requests', requestId, undefined, {
            'retry-after': String(Math.max(1, Math.ceil((pre.resetAt.getTime() - Date.now()) / 1000))),
          });
        }
      }

      // 3. Authentication
      const principal = await resolvePrincipal(request);
      activePrincipal = principal;
      if (!principal && authMode === 'required') {
        await recordSecurityEvent({
          type: 'authentication_failed',
          severity: 'medium',
          resource: options.resource,
          action,
          requestId,
          details: { reason: 'missing_or_invalid_credentials' },
        });
        return errorResponse(401, 'unauthorized', 'Authentication required', requestId, undefined, {
          'www-authenticate': 'Bearer',
        });
      }

      // 4. Tenant resolution — never from the request body.
      const companyId = principal?.companyId ?? '';
      if (tenantMode === 'required' && !companyId) {
        await recordSecurityEvent({
          type: 'authorization_denied',
          severity: 'high',
          resource: options.resource,
          action,
          requestId,
          principal: principal ?? null,
          details: { reason: 'principal_has_no_tenant' },
        });
        return errorResponse(403, 'tenant_required', 'Tenant context required', requestId);
      }

      // 5. Rate limit keyed on the authenticated principal (never on headers).
      if (rateLimit && principal) {
        const bucket = `${options.resource}:${action}:${principal.kind}:${principal.keyId ?? principal.userId}`;
        const result = await checkRateLimit(bucket, rateLimit.limit, rateLimit.windowMs);
        if (!result.allowed) {
          await recordSecurityEvent({
            type: 'rate_limit_exceeded',
            severity: 'medium',
            resource: options.resource,
            action,
            requestId,
            principal,
            companyId: companyId || null,
            details: { phase: 'principal', limit: rateLimit.limit },
          });
          return errorResponse(429, 'rate_limited', 'Too many requests', requestId, undefined, {
            'retry-after': String(Math.max(1, Math.ceil((result.resetAt.getTime() - Date.now()) / 1000))),
            'x-ratelimit-limit': String(rateLimit.limit),
            'x-ratelimit-remaining': '0',
          });
        }
      }

      // 6. API-key scopes
      if (principal && options.scope && principal.kind === 'apiKey') {
        const scopes = principal.scopes ?? [];
        if (!scopes.includes('*') && !scopes.includes(options.scope)) {
          await recordSecurityEvent({
            type: 'authorization_denied',
            severity: 'high',
            resource: options.resource,
            action,
            requestId,
            principal,
            companyId: companyId || null,
            details: { reason: 'missing_scope', requiredScope: options.scope },
          });
          return errorResponse(403, 'forbidden', 'API key is missing the required scope', requestId);
        }
      }

      // 7. Role based authorisation
      if (principal && !isAdmin(principal)) {
        if (options.roles && !options.roles.includes(principal.role)) {
          await recordSecurityEvent({
            type: 'authorization_denied',
            severity: 'high',
            resource: options.resource,
            action,
            requestId,
            principal,
            companyId: companyId || null,
            details: { reason: 'insufficient_role', requiredRoles: [...options.roles] },
          });
          return errorResponse(403, 'forbidden', 'Insufficient role for this operation', requestId);
        }
        if (options.companyRoles) {
          const companyRole = principal.companyRole ?? '';
          if (!companyRole || !options.companyRoles.includes(companyRole)) {
            await recordSecurityEvent({
              type: 'authorization_denied',
              severity: 'high',
              resource: options.resource,
              action,
              requestId,
              principal,
              companyId: companyId || null,
              details: { reason: 'insufficient_company_role', requiredRoles: [...options.companyRoles] },
            });
            return errorResponse(403, 'forbidden', 'Insufficient company role for this operation', requestId);
          }
        }
      }

      // 8. Validation: params (400), query (400), body (422)
      const rawParams = routeContext?.params ? await Promise.resolve(routeContext.params) : undefined;
      const params = options.params ? parseOrThrow(options.params, rawParams, 400, 'invalid_params', 'Invalid route parameters') : (rawParams as TParams);
      const query = options.query
        ? parseOrThrow(options.query, searchParamsToObject(request.nextUrl.searchParams), 400, 'invalid_query', 'Invalid query parameters')
        : (undefined as TQuery);

      // 9. Client-supplied tenant identifiers must match the principal.
      //    The RAW body is inspected before schema parsing: a strict schema
      //    would otherwise silently strip a spoofed `companyId` and the
      //    attempt would never reach the security event log.
      let body = undefined as TBody;
      try {
        if (options.body) {
          const raw = await readJsonBody(request);
          assertTenantAuthority(raw, companyId, tenantMode);
          body = parseOrThrow(options.body, raw, options.bodyStatus ?? 422, 'invalid_body', 'Invalid request body');
        }
        assertTenantAuthority(params, companyId, tenantMode);
        assertTenantAuthority(query, companyId, tenantMode);
        // Strip after validation so no handler can read a client-supplied
        // tenant, whether the schema was strict or permissive.
        stripTenantAuthority(body);
        stripTenantAuthority(params);
        stripTenantAuthority(query);
      } catch (error) {
        if (error instanceof ApiHttpError && error.code === 'tenant_mismatch') {
          await recordSecurityEvent({
            type: 'tenant_isolation_violation',
            severity: 'critical',
            resource: options.resource,
            action,
            requestId,
            principal: principal ?? null,
            companyId: companyId || null,
            details: { reason: 'client supplied a foreign companyId', expectedTenant: companyId },
          });
          error.recorded = true;
        }
        throw error;
      }

      const context: SecureContext<TBody, TQuery, TParams> = {
        request,
        requestId,
        principal: principal as Principal,
        companyId,
        body,
        query,
        params,
        assertTenant: (recordCompanyId: string | null | undefined) => {
          if (tenantMode === 'none' || !companyId) return;
          // Records belonging to another tenant are reported as "not found" so
          // the API cannot be used to enumerate other tenants' identifiers.
          if (recordCompanyId && recordCompanyId !== companyId) {
            throw new ApiHttpError(404, 'not_found', 'Not found');
          }
        },
        tenantWhere: <T extends Record<string, unknown>>(extra?: T) =>
          ({ ...(extra ?? {}), ...(tenantMode === 'none' || !companyId ? {} : { companyId }) }) as Record<string, unknown>,
      };

      const result = await handler(context);
      if (result instanceof NextResponse) return result;
      return jsonResponse(result ?? { success: true }, requestId, 200);
    } catch (error) {
      if (error instanceof ApiHttpError) {
        // Handlers that perform their own authorisation checks and throw a
        // security error still get an audit trail (exactly once).
        if (!error.recorded && SECURITY_ERROR_CODES.has(error.code)) {
          error.recorded = true;
          await recordSecurityEvent({
            type: error.code === 'tenant_mismatch' ? 'tenant_isolation_violation' : 'authorization_denied',
            severity: error.code === 'tenant_mismatch' ? 'critical' : 'high',
            resource: options.resource,
            action,
            requestId,
            principal: activePrincipal,
            companyId: activePrincipal?.companyId ?? null,
            details: { reason: error.message, source: 'handler' },
          });
        }
        return errorResponse(error.status, error.code, error.message, requestId, error.details);
      }
      if (error instanceof z.ZodError) {
        return errorResponse(options.bodyStatus ?? 422, 'invalid_body', 'Invalid request body', requestId, error.issues);
      }
      console.error('[secure-route]', options.resource, action, requestId, error);
      return errorResponse(500, 'internal_error', 'Internal server error', requestId);
    }
  };
}

function parseOrThrow<T>(
  schema: z.ZodType<T>,
  value: unknown,
  status: number,
  code: ApiErrorCode,
  message: string,
): T {
  const parsed = schema.safeParse(value);
  if (!parsed.success) {
    throw new ApiHttpError(status, code, message, parsed.error.issues);
  }
  return parsed.data;
}
